'use strict';
const C=LoganCollection;
let captureDraft=null,captureOrigin=null,collectionReadId=null,collectionReadQuery='';
function captureRemember(){state.captureDraft=JSON.parse(JSON.stringify(captureDraft));save();}
function capturePatch(key,value){captureDraft[key]=value;captureDraft.force=false;if(['begin','end','targetId'].includes(key))captureDraft.expanded=false;captureRemember();}
function captureTarget(){return C.target(captureDraft?.targetId);}
function captureIssue(){return state.issues.find(i=>i.id===captureDraft?.issueId);}
function captureTime(value){return esc((value||'未知').replace('T',' '));}
function captureTargetCard(t){return !t?'<div class="notice">尚未识别目标。请选择合成目录中的安装实例或 Web 会话；搜索不到时可保存草稿或导入日志。</div>':`<section class="capture-target-card"><div class="row"><strong>${esc(t.device)}</strong>${badge(t.platform)}</div><p>${esc(t.project)} / ${esc(t.app)} / ${esc(t.environment)}</p><dl class="product-facts"><dt>安装 / 会话</dt><dd>${esc(t.instance)}</dd><dt>最近已知构建</dt><dd>${esc(t.latestVersion||'未知')} / ${esc(t.latestBuild||'未知')} · 不代表故障构建</dd><dt>最近联系</dt><dd>${esc(t.lastSeen)}</dd><dt>采集能力</dt><dd>${t.profile==='day'?'按日混合文件，解析后筛选':t.profile==='precise'?'支持指定时段与类型':'页面未运行，不能接收指令'}</dd><dt>能力来源</dt><dd>${esc(t.source)} · ${esc(t.capabilityAt)}</dd></dl></section>`;}
function captureIssueOptions(value){return '<option value="">暂不关联工单</option>'+state.issues.map(i=>`<option value="${i.id}" ${i.id===value?'selected':''}>${esc(i.id+' · '+i.title+(i.status==='已解决'?' · 已解决':''))}</option>`).join('');}
function captureSetIssue(value){capturePatch('issueId',value);captureShow();}
function captureSelectTarget(value){capturePatch('targetId',value);const t=captureTarget();captureDraft.types=t?.kinds.slice()||[];captureDraft.app=t?.app||captureDraft.app;captureRemember();captureShow();}
function captureSearchTargets(value){capturePatch('search',value);const app=captureDraft.app;document.querySelectorAll('[data-capture-target]').forEach(el=>el.hidden=!!app&&el.dataset.app!==app||!el.dataset.search.toLowerCase().includes(value.toLowerCase()));}
function captureSetApp(value){captureDraft.app=value;captureDraft.targetId='';captureDraft.types=[];captureDraft.expanded=false;captureRemember();captureShow();}
startAcquisitionFromWorkspace=function(id){
 const i=id?state.issues.find(i=>i.id===id):null;
 captureOrigin=id&&['workbench','logcenter'].includes(page)?page:null;
 const prior=state.captureDraft;
 if(prior&&(prior.originIssue||'')===(id||'')){captureDraft=JSON.parse(JSON.stringify(prior));captureDraft.step=1;}
 else{const t=i?C.targets.find(t=>t.device===i.device):null;captureDraft={step:1,originIssue:id||'',issueId:i?.status==='已解决'?'':i?.id||'',targetId:t?.id||'',app:t?.app||'',search:'',title:i?.title||'',begin:i?.begin||'',end:i?.end||'',types:t?.kinds.slice()||[],budget:'32',ttl:'30',notify:true,expanded:false};}
 captureRemember();captureShow();
};
deskStartCollection=function(){startAcquisitionFromWorkspace(issue().id);};
function captureScopeView(){try{const t=captureTarget(),scope=P.captureScope(captureDraft.begin,captureDraft.end,t?.profile);return `<div class="capture-range"><span>希望获取的时段</span><strong>${captureTime(captureDraft.begin)} — ${captureTime(captureDraft.end)}</strong><span>预计采集范围</span><strong>${captureTime(scope.begin)} — ${captureTime(scope.end)}</strong><small>北京时间 UTC+08:00；实际返回的事件范围将在解析后显示。</small></div>${scope.expanded?`<label class="check notice"><input type="checkbox" id="capture-expanded" ${captureDraft.expanded?'checked':''} onchange="capturePatch('expanded',this.checked)">确认按日采集，预计包含故障时段以外的内容</label>`:''}`;}catch(e){return `<p class="notice">${esc(e.message)}</p>`;}}
function captureRefreshScope(){const box=$('#capture-range');if(box)box.innerHTML=captureScopeView();}
function captureSampleTime(){const t=captureTarget();captureDraft.begin=t.sampleDay+'T10:40';captureDraft.end=t.sampleDay+'T10:45';captureDraft.expanded=false;captureRemember();captureShow();}
function captureKind(kind,checked){const set=new Set(captureDraft.types);checked?set.add(kind):set.delete(kind);capturePatch('types',[...set]);}
function captureStep(n){try{if(n>1){const t=captureTarget();if(!t)throw Error('先选择推送接收对象');C.requirePush(t);if(['web-offline','unsupported'].includes(t.profile))throw Error('目标不能接收指令；可保存草稿，或改用手动导入');if(captureIssue()?.status==='已解决')throw Error('此工单已解决，请选择暂不关联，或先回到工单重新调查');}if(n===3){if(!captureDraft.title.trim())throw Error('请简要描述本次要排查的现象');const scope=P.captureScope(captureDraft.begin,captureDraft.end,captureTarget().profile);if(scope.expanded&&!captureDraft.expanded)throw Error('请先确认扩大至整日的预计范围');if(!captureDraft.types.length)throw Error('至少选择一种支持的日志');}captureDraft.step=n;captureRemember();captureShow();}catch(e){$('#capture-error').textContent=e.message;}}
function capturePushTarget(t){if(!t)return '<div class="notice">请选择接收对象，核对其推送绑定。设备或会话标识用于查找绑定，不是直接上传入口。</div>';const b=C.pushBinding(t);return `<section class="capture-target-card"><h3>推送路由</h3><dl class="product-facts"><dt>通道</dt><dd>${esc(b.channel)}</dd><dt>接收对象</dt><dd>${esc(t.device+' / '+t.instance)}</dd><dt>推送绑定</dt><dd>${esc(b.id||'未绑定')} · ${esc(b.recipient||'无接收标识')}</dd><dt>绑定状态</dt><dd>${b.ready?'可模拟提交；不表示设备在线或已送达':'不可发送；保存草稿或上传已有文件'}</dd></dl><small>${esc(b.source)}。绑定由应用环境配置；原型不使用真实 Token。</small></section>`;}
function collectionPushProgress(r){const p=r.product?.push;if(!p)return '';const confirmed=r.events.some(e=>e.text.includes('SDK 已确认')),delivered=r.events.some(e=>e.text.includes('回执已收到'));return `<section class="product-card"><h3>回捞推送</h3><p><strong>${esc(p.id)}</strong> · ${esc(p.status)} · 本地模拟</p><dl class="product-facts"><dt>推送通道 / 绑定</dt><dd>${esc(p.binding.channel+' / '+p.binding.id)}</dd><dt>接收标识</dt><dd>${esc(p.binding.recipient)}</dd><dt>指令关联</dt><dd>${esc(p.command.requestId)} · 回捞已有日志</dd><dt>提交时间</dt><dd>${p.submittedAt?esc(new Date(p.submittedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))+' +08:00':'尚未发送'}</dd><dt>通道回执</dt><dd>${esc(p.receiptId||'暂无接受回执')}</dd><dt>设备送达</dt><dd>${delivered?'已收到送达回执':r.scenario==='noreceipt'?'未知 · 渠道无送达回执':'尚无送达证据'}</dd><dt>SDK 响应</dt><dd>${confirmed?'已确认回捞指令':r.status==='无可用日志'?'已响应：无可用日志':r.status==='设备不支持'?'已响应：不支持所需日志':'尚未确认'}</dd></dl><details><summary>查看已保存的回捞指令</summary><p>故障范围按目标能力转换为以下指令范围；保持本次提交快照。</p><p>${captureTime(p.command.begin)} — ${captureTime(p.command.end)} · 北京时间</p><p>${esc(p.command.types.join('、'))} · 上传上限 ${p.command.budgetMiB} MiB · 有效期 ${p.command.ttlMinutes} 分钟</p></details><p class="muted">通道接受 ≠ 设备送达 ≠ SDK 确认 ≠ 日志可读。文件由客户端在响应指令后另行上传。</p></section>`;}
function captureShow(){
 const d=captureDraft,t=captureTarget(),i=captureIssue(),step=d.step;
 let body='';
 if(step===1){body=`<p class="muted">先确定应用的推送通道与接收对象，再下发日志回捞指令。客户端收到指令后查找本地日志并上传；推送本身不携带日志。此处仅模拟推送。</p><label for="capture-app">应用 / 环境</label><select id="capture-app" onchange="captureSetApp(this.value)"><option value="">全部演示应用 · 隔离演练</option>${[...new Set(C.targets.map(t=>t.app))].map(a=>`<option ${a===d.app?'selected':''}>${esc(a)}</option>`).join('')}</select><label for="capture-target-search">查找推送对象（设备 / 安装 / Web 会话）</label><input id="capture-target-search" value="${esc(d.search)}" placeholder="例如 demo-A17 或 browser-demo-01" oninput="captureSearchTargets(this.value)"><div class="capture-targets">${C.targets.map(t=>`<button type="button" data-capture-target data-app="${esc(t.app)}" data-search="${esc(t.device+' '+t.instance+' '+t.platform)}" ${d.app&&d.app!==t.app||!(t.device+' '+t.instance+' '+t.platform).toLowerCase().includes(d.search.toLowerCase())?'hidden':''} class="${d.targetId===t.id?'chosen':''}" onclick="captureSelectTarget('${t.id}')"><strong>${esc(t.device)}</strong><span>${esc(t.platform+' · '+t.instance)}</span><small>${C.pushBinding(t).ready?'已绑定合成推送通道':'无可用推送绑定'}</small></button>`).join('')}</div>${capturePushTarget(t)}<details><summary>设备能力与版本线索</summary>${captureTargetCard(t)}</details><label for="new-capture-issue">关联工单（可选）</label><select id="new-capture-issue" onchange="captureSetIssue(this.value)">${captureIssueOptions(d.issueId)}</select>${d.originIssue?'<small>从工单进入的现场信息是待核对线索，不作为设备或日志实际身份。</small>':''}${i?`<div class="notice">工单预期：${esc(i.device)} · ${esc(i.version||'未知')} / ${esc(i.build||'未知')}${t&&i.device!==t.device?'。目标与工单设备不同，请核对。':''}${i.status==='已解决'?'。已解决工单不能直接追加采集，请暂不关联或先重新调查。':''}</div>`:''}${d.originIssue&&!d.issueId?'<div class="notice">当前按独立采集处理；原工单和关闭记录保留。</div>':''}<div class="toolbar">${btn('上传日志文件（选择工单）',"captureRemember();closeModal();openLogImport()",'textbutton')}${btn('重新填写本次草稿','captureRestart()','textbutton')}</div>`;}
 else if(step===2){body=`<div class="capture-compact"><strong>${esc(t.device)}</strong> · ${esc(t.platform+' / '+t.app)}${btn('更换目标','captureStep(1)','textbutton')}</div><label for="capture-title">本次排查的现象</label><input id="capture-title" maxlength="100" value="${esc(d.title)}" placeholder="例如：登录超时后一直转圈" oninput="capturePatch('title',this.value)"><div class="form-grid"><div><label for="new-capture-begin">故障范围开始 · 北京时间</label><input type="datetime-local" id="new-capture-begin" value="${esc(d.begin)}" onchange="capturePatch('begin',this.value);captureRefreshScope()"></div><div><label for="new-capture-end">故障范围结束 · 北京时间</label><input type="datetime-local" id="new-capture-end" value="${esc(d.end)}" onchange="capturePatch('end',this.value);captureRefreshScope()"></div></div>${btn('使用此目标的合成样例时段','captureSampleTime()','textbutton')}<div id="capture-range">${captureScopeView()}</div><fieldset><legend>指令要求回捞的日志类型</legend>${t.kinds.map(k=>`<label class="check"><input type="checkbox" ${d.types.includes(k)?'checked':''} ${t.profile==='day'?'disabled':''} onchange="captureKind('${k}',this.checked)">${esc(k)}</label>`).join('')}<small>${t.profile==='day'?'目标只提供混合文件，返回后再按类型筛选。':'只显示此目标声明支持的类型。'}</small></fieldset><details class="capture-advanced"><summary>高级设置 · 上传上限 ${esc(d.budget)} MiB / 等待 ${esc(d.ttl)} 分钟</summary><div class="form-grid"><label>上传上限<select onchange="capturePatch('budget',this.value)">${['8','32','64'].map(v=>`<option ${d.budget===v?'selected':''}>${v}</option>`).join('')}</select></label><label>等待设备的期限<select onchange="capturePatch('ttl',this.value)">${['15','30','60'].map(v=>`<option ${d.ttl===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="check"><input type="checkbox" ${d.notify?'checked':''} onchange="capturePatch('notify',this.checked)">结果就绪或失败时生成本地提醒</label></details>`;}
 else{body=`<h3>${esc(d.title)}</h3>${capturePushTarget(t)}<p>${esc(t.project+' / '+t.app+' / '+t.environment)}</p><dl class="product-facts"><dt>采集目标</dt><dd>${esc(t.device+' · '+t.instance+' · '+t.platform)}</dd><dt>关联工单</dt><dd>${i?esc(i.id+' · '+i.title):'暂不关联，取得日志后可建立问题'}</dd><dt>工单预期构建</dt><dd>${esc(i?.build||'未知 / 无工单')}</dd><dt>最近已知构建</dt><dd>${esc(t.latestBuild||'未知')} · 合成目标目录</dd><dt>日志实际构建</dt><dd>尚未取得日志，未知</dd><dt>材料 / 上限</dt><dd>${esc(d.types.join('、'))} / ${esc(d.budget)} MiB</dd><dt>等待期限</dt><dd>${esc(d.ttl)} 分钟</dd></dl>${captureScopeView()}<div class="notice"><strong>推送指令 → 客户端响应 → 查找本地日志 → 上传 → 解析阅读</strong><p>下方发送会创建回捞请求并模拟提交至所示通道。通道接受不代表设备送达；SDK 确认后才开始回捞文件。没有日志时返回明确结果，不补录历史。</p></div><details><summary>本地演练结果</summary><label for="capture-scenario">模拟推送与执行结果</label><select id="capture-scenario" onchange="capturePatch('scenario',this.value)">${Object.entries({success:'全部成功',pushfail:'推送通道拒绝',timeout:'设备响应超时',noreceipt:'渠道无送达回执，SDK 后续响应',partial:'部分上传成功',unsupported:'SDK 不支持',uploadfail:'上传失败',empty:'客户端无可用日志',parsefail:'解析失败'}).map(([value,label])=>`<option value="${value}" ${d.scenario===value?'selected':''}>${label}</option>`).join('')}</select></details><label class="check"><input type="checkbox" ${d.force?'checked':''} onchange="capturePatch('force',this.checked);captureDraft.force=this.checked;captureRemember()">即使已有相同目标和范围的进行中请求，也新建独立请求</label>`;}
 openModal(d.originIssue?'补充采集 · 回捞设备日志':'回捞设备日志',`<div class="capture-wizard"><ol class="capture-steps">${['确认推送目标','配置回捞指令','确认并推送'].map((v,n)=>`<li class="${step===n+1?'active':''}" ${step===n+1?'aria-current="step"':''}>${n+1} ${v}</li>`).join('')}</ol><div class="capture-body">${body}<p id="capture-error" class="error" role="alert"></p></div><div class="capture-footer"><div>${btn('保存草稿并退出','captureSaveExit()')}${btn('取消','closeModal()')}</div><div>${step>1?btn('上一步',`captureStep(${step-1})`):''}${btn(step===3?'发送回捞推送（模拟）':'下一步',step===3?'captureCommit()':`captureStep(${step+1})`,'primary')}</div></div></div>`,true);
 $('#modal').classList.add('capture-dialog');
}
const captureOldClose=closeModal;
closeModal=function(){$('#modal').classList.remove('capture-dialog');captureOldClose();};
function captureRestart(){const origin=captureDraft.originIssue;delete state.captureDraft;save();startAcquisitionFromWorkspace(origin||undefined);}
function captureSaveExit(){captureRemember();closeModal();toast('草稿已保留，下次新建可继续；尚未发送请求');}
function captureCommit(){const backup=JSON.stringify(state);try{const r=C.create(state,captureDraft,M,P);r.scenario=captureDraft.scenario||'success';C.dispatch(r,M);delete state.captureDraft;if(!save()){state=JSON.parse(backup);throw Error('本地存储不足，请保留草稿后重试；请求未创建');}const origin=captureOrigin;closeModal();workUI.collectionKey=r.product.stableKey;workUI.collectionMode='push';workUI.collectionQuery='';workUI.collectionStatus='';collectionReadId=null;if(r.issueId)state.active=r.issueId;if(origin&&r.issueId){desk.tool='collect';page=origin;location.hash=origin;render();}else{deskCollectOrigin=null;go('collectioncenter');}toast(r.status==='推送失败'?'模拟推送被拒绝，请在进度中查看原因与重试':'回捞推送已模拟提交，等待客户端响应');}catch(e){$('#capture-error').textContent=e.message;}}

// Independent requests have no issue object in persistent storage. The lightweight
// descriptor below is only a label adapter for the existing collection rail.
const collectionOldSources=fullLogSources;
fullLogSources=function(){return collectionOldSources().map(x=>x.request.product?.stableKey?{...x,key:x.request.product.stableKey}:x).concat((state.collectionRequests||[]).map(r=>({request:r,key:r.product.stableKey,independent:true,issue:{id:'未关联',title:'独立采集',version:null,build:null,requests:[]}})));};
const collectionOldSync=syncCollection;
syncCollection=function(x){if(x?.independent){requestId=x.request.id;workUI.collectionKey=x.key;return;}collectionOldSync(x);};
function collectionByKey(key){return fullLogSources().find(x=>x.key===key);}
function collectionScenario(key,value){const r=collectionByKey(key)?.request;if(r&&!r.step){r.scenario=value;save();}}
function collectionFixture(t){
 if(t.platform==='Web'){const temp={issues:[],logSequence:1},owner={id:'sample',logAssets:[]};temp.issues=[owner];const a=L.webSample(temp,owner);return {version:a.version,build:a.build,platform:'Web',source:'返回的 Web 合成文件声明',records:a.files[0].text.split('\n').map((line,n)=>{const x=JSON.parse(line);return {...x,...a.sampleRecords[n],content:x.message,sourceVerified:!!x.file};})};}
 return {version:'3.8.1',build:'38107',platform:'Native',source:'返回的 Native 合成文件声明',records:records.map(r=>({...r,time:'2026-10-19T'+r.time+'+08:00',scene:'login',sourceVerified:!!r.file}))};
}
const collectionOldAdvance=M.advance;
M.advance=function(r){const before=r.events.length;C.beginPush(r);collectionOldAdvance(r);C.recordPush(r);if(r.product?.flowVersion===2&&!r.issueId)r.events.slice(before).forEach(e=>e.text=e.text.replace('可查文件自动关联工单','可查文件保留为独立采集材料，尚未关联工单'));if(r.product?.flowVersion===2&&r.step>=4&&r.files.some(f=>f.status!=='上传失败')&&!r.product.observed){const data=collectionFixture(r.product.target);data.records=data.records.filter(row=>r.files.some(f=>f.status!=='上传失败'&&(f.name.startsWith('混合日志')||f.name.startsWith(/Network/.test(row.module)?'网络日志':'应用日志'))));C.observe(r,data);}};
const collectionOldTasks=M.tasks;
M.tasks=function(i){return collectionOldTasks(i).map(t=>{const r=i.requests.find(r=>r.task===t.id);if(r?.product?.flowVersion!==2)return t;const data=r.product.observed;const rows=(data?.records||[]).filter(row=>t.types.includes('混合日志')||t.types.includes(/Network/.test(row.module)?'网络日志':'应用日志'));return {...t,version:data?.version||null,build:data?.build||null,platform:r.platform,records:rows,versionOrigin:data?.build?'captured':'unknown',begin:rows[0]?.time?.slice(0,16)||t.begin};});};
const collectionOldRetry=retryInlineCollection;
retryInlineCollection=function(key){const x=collectionByKey(key);if(!x?.request.product?.flowVersion)return collectionOldRetry(key);const r=x.request,temp=x.independent?{requests:state.collectionRequests,version:null,build:null}:x.issue,result=M.retry(state,temp,r);if(!result)return toast('没有需要重试的文件');if(!result.duplicate){const next=result.request;next.issueId=r.issueId||null;next.version=null;next.build=null;next.product.stableKey='collection/'+next.id;next.product.observed=null;if(r.product.push)next.product.push=C.preparePush(next);delete next.product.assets;next.product.expected=JSON.parse(JSON.stringify(r.product.expected));}workUI.collectionKey=result.request.product.stableKey;workUI.collectionMode='push';save();render();};
const collectionOldRail=collectionRail;
collectionRail=function(all,x){let html=collectionOldRail([...all].sort((a,b)=>(Date.parse(b.request.createdAt)||0)-(Date.parse(a.request.createdAt)||0)),x);for(const entry of all){const r=entry.request,t=r.product?.target;if(!t)continue;html=html.replace(`<b>${r.id}</b>`,`<b>${r.id} · ${esc(r.product.title)}</b>`).replace(`${esc(r.device)} · ${esc(entry.issue.id)}`,`${esc(t.app)} · ${esc(r.device)}<br>${captureTime(r.begin)} · ${r.issueId||'未关联工单'}`);}return html;};
function collectionMaterialSummary(r){const c=C.coverage(r),data=r.product?.observed;return `<section class="product-card"><h3>返回材料</h3><p>请求材料 ${r.types.length} 类 · 已收到 ${r.files.filter(f=>f.status!=='上传失败').length} 份文件 · 可读 ${r.files.filter(f=>f.status==='可查').length} 份</p><dl class="product-facts"><dt>希望获取</dt><dd>${captureTime(r.begin)} — ${captureTime(r.end)}</dd><dt>预计采集</dt><dd>${captureTime(r.product.scope.begin)} — ${captureTime(r.product.scope.end)}</dd><dt>事件观察范围</dt><dd>${c.begin?captureTime(c.begin)+' — '+captureTime(c.end):'等待解析，无可读事件'}</dd><dt>日志实际构建</dt><dd>${esc(data?.build||'未知')} · ${esc(data?.source||'等待文件声明')}</dd></dl><p class="notice">${esc(c.label)}。所有返回内容为固定合成样例，不随所选日期生成现场事实。</p>${c.begin?`<p>${Date.parse(c.begin)<Date.parse(r.end+'+08:00')&&Date.parse(c.end)>=Date.parse(r.begin+'+08:00')?'样例事件与希望获取的时段有重叠，不能据此断言完整覆盖。':'样例事件未命中希望获取的时段，请调整范围或补充其他材料。'}</p>`:''}</section>`;}
function collectionNext(r){if(r.task)return r.status==='部分成功'?'已有部分可读日志。先阅读已有材料，再重试缺失部分。':'日志已可读。核对事件时间和构建，再加入调查。';return ({'已取消':'请求已停止；已有记录保留。迟到回执不会重新激活请求。','解析失败':'文件已收到，可重新解析原文件，无需再次推送。','无可用日志':'设备未返回可用日志。检查故障日期，或改用手动导入。','设备响应超时':'等待已结束。可以重试未完成部分，或导入本地日志。','推送失败':'推送通道未接受指令，请核对绑定后重试。','通道已接受':'推送通道已接受指令，等待设备送达与 SDK 响应；尚无返回日志。','设备已送达':'已收到设备送达回执，等待 SDK 执行回捞。','采集中':'SDK 已确认指令，正在查找本地日志并上传。','解析中':'已收到客户端文件，等待解析完成后阅读。','待推送':'请求已创建。使用下方演练按钮发送，随后等待设备响应。'}[r.status]||'正在等待设备与文件处理结果，可在下方查看各阶段。');}
const collectionOldBody=inlineCollection;
inlineCollection=function(x){const r=x.request;let html=collectionOldBody(x);html=html.replace('实际：','预计采集：').replace('采集范围与结果覆盖','采集计划与文件处理');if(r.product?.flowVersion!==2)return html;
 // The previous range card described a plan as an outcome. Replace that card,
 // while retaining its existing stage controls, failures, retries and receipts.
 const boundary=html.indexOf('<div class="pane-header">');if(boundary>=0)html=html.slice(boundary);
 html=html.replace('发送采集指令','发送回捞推送（模拟）').replace('推进下一步','模拟下一阶段回执').replace('运行到结果（演示）','模拟后续回执与文件返回');
 html=html.replace('onchange="request().scenario=this.value;save()"',`onchange="collectionScenario('${x.key}',this.value)"`);
 const panelStart=html.indexOf('<div class="panel">');if(panelStart>=0)html=html.slice(panelStart);
 const timelineStart=html.indexOf('<div class="panel"><h3>回调与通知时间线</h3>');let timeline='';if(timelineStart>=0){timeline='<details class="panel"><summary>推送与处理时间线</summary>'+html.slice(timelineStart)+'</details>';html=html.slice(0,timelineStart);}
 const t=r.product.target;
 const actions=r.issueId?btn('返回关联调查',`deskOpenIssue('${r.issueId}')`):btn('关联工单或建立问题',`collectionAssociateForm('${r.id}')`);
 return `<section class="capture-detail-head"><span class="eyebrow">回捞进度 / ${r.id}</span><h2>${esc(r.product.title)}</h2><p>${esc(t.project+' / '+t.app+' / '+t.environment)}</p><p>本次材料：${esc(r.types.join('、'))}${r.parent?' · 仅重试 '+esc(r.parent)+' 的未完成部分':''}</p><p><strong>${esc(t.device)}</strong> · ${esc(t.instance+' · '+t.platform)} · ${r.issueId||'未关联工单'} · ${esc(new Date(r.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}))} +08:00</p><div class="capture-next">${badge(r.status)}<p>${collectionNext(r)}</p><div class="toolbar">${r.task?btn('阅读返回材料',`openSourceLogs('${x.key}')`,'primary'):''}${r.status==='解析失败'?btn('重新解析返回文件',`collectionReparse('${r.id}')`,'primary'):''}${actions}</div></div><details><summary>目标信息来源与版本线索</summary>${captureTargetCard(t)}<p>工单预期构建：${esc(r.product.expected?.build||'未知 / 无工单')}；日志实际构建：${esc(r.product.observed?.build||'等待返回，未知')}。预期和最近已知版本都不替代日志实际版本。</p></details></section>${collectionPushProgress(r)}${html}${collectionMaterialSummary(r)}${timeline}`;
};
const collectionOldView=views.collectioncenter;
views.collectioncenter=function(){if(collectionReadId)return collectionReadView();return collectionOldView().replace('左侧选择请求，右侧直接追踪推送、上传和解析，或运行本地演示。','通过推送下发回捞指令，等待客户端响应、日志上传和解析。可独立发起，也可关联工单继续调查。');};
const collectionOldOpen=openSourceLogs;
openSourceLogs=function(key){const x=collectionByKey(key);if(!x?.independent)return collectionOldOpen(key);if(!x.request.task)return toast('日志尚不可读，请查看文件处理结果');collectionReadId=x.request.id;collectionReadQuery='';page='collectioncenter';location.hash=page;render();};
function collectionReadView(){const r=C.find(state,collectionReadId);if(!r){collectionReadId=null;return collectionOldView();}const rows=(r.product.observed?.records||[]).filter(row=>r.files.some(f=>f.status==='可查'&&(f.name.startsWith('混合日志')||f.name.startsWith(/Network/.test(row.module)?'网络日志':'应用日志'))));return heading('阅读返回材料 · '+r.id,'独立采集尚未关联问题。可以先核对内容，再建立调查。')+`<div class="toolbar">${btn('返回回捞进度','collectionReadId=null;render()')}${btn('关联工单或建立问题',`collectionAssociateForm('${r.id}')`,'primary')}${btn('下载正文',`collectionDownload('${r.id}')`)}${btn('重新解析返回文件',`collectionReparse('${r.id}')`)}</div>${collectionMaterialSummary(r)}<section class="panel"><label for="collection-read-query">搜索返回事件</label><input id="collection-read-query" placeholder="关键词、模块或请求标识" value="${esc(collectionReadQuery)}" oninput="collectionReadQuery=this.value;collectionFilterRows()"><p>${rows.length} 条合成事件 · 原始时间与字段保留</p>${rows.map((row,n)=>`<details data-collection-row data-search="${esc(JSON.stringify(row))}"><summary><span>${captureTime(row.time)}</span> ${esc(row.level+' · '+row.module)} · ${esc(row.content)}</summary><pre>${esc(JSON.stringify(row,null,2))}</pre></details>`).join('')}<p id="collection-read-empty" hidden>没有匹配事件，请调整关键词。</p></section>${collectionParseHistory(r)}`;}
function collectionFilterRows(){let count=0;document.querySelectorAll('[data-collection-row]').forEach(row=>{row.hidden=!row.dataset.search.toLowerCase().includes(collectionReadQuery.toLowerCase());if(!row.hidden)count++;});$('#collection-read-empty').hidden=!!count;}
function collectionDownload(id){const r=C.find(state,id),rows=(r.product.observed?.records||[]).filter(row=>r.files.some(f=>f.status==='可查'&&(f.name.startsWith('混合日志')||f.name.startsWith(/Network/.test(row.module)?'网络日志':'应用日志'))));file(id+'-synthetic.jsonl',rows.map(x=>JSON.stringify(x)).join('\n'));}
const collectionOldDownload=downloadSourceSample;
downloadSourceSample=function(key){const r=collectionByKey(key)?.request;return r?.product?.flowVersion===2?collectionDownload(r.id):collectionOldDownload(key);};
function collectionParseHistory(r){const assets=r.product.assets||[];return assets.length?`<section class="panel"><h3>重新解析历史</h3>${assets.map(a=>a.runs.map(run=>`<p>${a.id} / ${run.id} · ${esc(run.status)} · ${run.records.length} 条记录</p>`).join('')).join('')}<p>原请求的状态与日志不覆盖；关联工单后可在日志资料库继续操作这些解析批次。</p></section>`:'';}
function collectionReparse(id){const r=C.find(state,id);if(!r?.product.observed)return toast('尚未收到文件，无法重新解析');if(r.issueId)return reparseCollection(r.product.stableKey);const owner={id:'unlinked-'+id,logAssets:r.product.assets||[]};try{let a=owner.logAssets[0];if(a){const run=L.reparse(a,{format:'auto',policy:'strict'});L.advance(a,run);L.advance(a,run);L.advance(a,run);}else{const rows=r.product.observed.records.filter(row=>r.files.some(f=>['已上传','可查','解析失败'].includes(f.status)&&(f.name.startsWith('混合日志')||f.name.startsWith(/Network/.test(row.module)?'网络日志':'应用日志'))));a=L.importFiles(state,owner,{platform:r.platform,origin:'collection',identityUnknown:!!r.product.aliyun,sourceKey:r.product.stableKey,device:r.device,version:r.version,build:r.build,begin:r.begin,end:r.end,files:[{name:r.id+'.jsonl',text:rows.map(x=>JSON.stringify({...x,message:x.content})).join('\n')}],format:'auto',policy:'strict'}).asset;L.advance(a,a.runs[0]);L.advance(a,a.runs[0]);L.advance(a,a.runs[0]);}r.product.assets=owner.logAssets;save();openModal('独立解析结果',`${collectionParseHistory(r)}<p>已重新解析保存的合成文件，没有再次向设备发送请求。</p>${btn('返回','closeModal()')}${btn('关联并打开完整日志工作台',`closeModal();collectionAssociateForm('${id}')`,'primary')}`,true);}catch(e){toast(e.message);}}
function collectionAssociateForm(id){const r=C.find(state,id);openModal('把采集材料接入调查',`<form onsubmit="collectionAssociateSubmit(event,'${id}')"><p>${esc(r.id+' · '+r.device)}。关联只增加调查关系，不改变请求身份、原文件和版本。</p><label for="collection-link-issue">关联已有工单，或新建问题</label><select id="collection-link-issue"><option value="">新建问题</option>${state.issues.filter(i=>i.status!=='已解决').map(i=>`<option value="${i.id}">${esc(i.id+' · '+i.title+' · '+i.device)}</option>`).join('')}</select><label for="collection-link-title">新问题标题（选择新建时填写）</label><input id="collection-link-title" value="${esc(r.product.title)}" maxlength="100"><p>已有工单的设备和构建可能不同，请核对目标；采集元数据保留原值。</p><label class="check"><input id="collection-link-confirm" type="checkbox">已核对目标与调查用途</label><p id="collection-link-error" role="alert" class="error"></p><div class="toolbar"><button class="primary">关联并继续调查</button><button type="button" onclick="closeModal()">取消</button></div></form>`,true);}
function collectionAssociateSubmit(e,id){e.preventDefault();const backup=JSON.stringify(state);try{if(!$('#collection-link-confirm').checked)throw Error('请核对目标与调查用途');const r=C.find(state,id);let issueId=$('#collection-link-issue').value;if(!issueId){const title=$('#collection-link-title').value.trim();if(!title)throw Error('请填写新问题标题');issueId='ISS-'+(Math.max(1041,...state.issues.map(i=>Number(i.id.replace('ISS-',''))||0))+1);state.issues.push({id:issueId,title,description:r.product.title,device:r.device,platform:r.platform,app:r.product.target.app,environment:r.product.target.environment,version:r.version||'',build:r.build||'',begin:r.begin,end:r.end,priority:'P1',owner:'待分配',status:'调查中',requests:[],evidence:[],updates:[],analysis:null,verified:false});}const i=state.issues.find(i=>i.id===issueId);C.associate(state,id,issueId);if(r.product.assets){i.logAssets=(i.logAssets||[]).concat(r.product.assets.map(a=>({...a,issueId})));delete r.product.assets;}if(!save()){state=JSON.parse(backup);throw Error('存储不足，关联未保存');}closeModal();collectionReadId=null;state.active=issueId;desk.issueKeys[issueId]=r.product.stableKey;workUI.logKey=r.product.stableKey;deskOpenIssue(issueId);toast('材料已关联，原采集身份和历史保持不变');}catch(err){$('#collection-link-error').textContent=err.message;}}
// New requests reparse the actual saved fixture, never the current issue's build.
const collectionOldReparse=reparseCollection;
reparseCollection=function(key){const x=collectionByKey(key),r=x?.request;if(r?.product?.flowVersion!==2)return collectionOldReparse(key);if(x.independent)return collectionReparse(r.id);const old=(x.issue.logAssets||[]).find(a=>a.sourceKey===key);if(old)return openReparse(old.id);try{const rows=r.product.observed?.records||[];const a=L.importFiles(state,x.issue,{platform:r.platform,origin:'collection',identityUnknown:!!r.product.aliyun,sourceKey:key,device:r.device,version:r.version,build:r.build,begin:r.begin,end:r.end,files:[{name:r.id+'.jsonl',text:rows.filter(row=>r.files.some(f=>['已上传','可查','解析失败'].includes(f.status)&&(f.name.startsWith('混合日志')||f.name.startsWith(/Network/.test(row.module)?'网络日志':'应用日志')))).map(row=>JSON.stringify({...row,message:row.content})).join('\n')}],format:'auto',policy:'strict'}).asset;save();selectAssetRun(a,a.runs[0]);}catch(e){toast(e.message);}};
const collectionOldDeskScope=deskScope;
deskScope=function(x){if(x?.request.product?.flowVersion!==2)return collectionOldDeskScope(x);const r=x.request,t=currentTask();return `<section class="desk-scope"><div><strong>${esc(r.device)}</strong><p>${esc(r.platform)} · 日志实际版本 ${esc(t?.version||'未知')} / ${esc(t?.build||'未知')}</p><small>工单预期 ${esc(r.product.expected?.build||'未知')} · 设备最近已知 ${esc(r.product.target.latestBuild||'未知')}</small></div><div><small>希望获取 · 北京时间</small><p>${captureTime(r.begin)} — ${captureTime(r.end)}</p></div><div>${btn('查看采集来源',`openSourceCollection('${r.product.stableKey}')`)}${btn('进入关联调查',`deskOpenIssue('${x.issue.id}')`)}</div></section>`;};
const collectionOldDeskSources=deskSources;
deskSources=function(){return collectionOldDeskSources().filter(x=>!x.independent);};
const collectionOldLogView=views.logcenter;
views.logcenter=function(){const independent=(state.collectionRequests||[]).filter(r=>r.task);return (independent.length?`<section class="panel"><h3>未关联工单的采集材料 · ${independent.length}</h3>${independent.map(r=>`<div class="row"><span>${esc(r.product.title)} · ${esc(r.device)} · ${r.id}</span>${btn('阅读独立采集',`openSourceLogs('${r.product.stableKey}')`)}</div>`).join('')}</section>`:'')+collectionOldLogView();};
const collectionOldOpenDetail=openSourceCollection;
openSourceCollection=function(key){collectionReadId=null;collectionOldOpenDetail(key);};
const collectionOldExport=exportParseRecord;
exportParseRecord=function(key){const r=collectionByKey(key)?.request;if(r?.product?.flowVersion!==2)return collectionOldExport(key);file(r.id+'-collection-record.json',JSON.stringify({origin:'local-synthetic',id:r.id,issueId:r.issueId,target:r.product.target,push:r.product.push||null,expected:r.product.expected,requestedWindow:{begin:r.begin,end:r.end},plannedWindow:r.product.scope,observed:r.product.observed,coverage:C.coverage(r),status:r.status,files:r.files,events:r.events},null,2));};
const collectionOldParseView=parseView;
parseView=function(x){if(x?.request.product?.flowVersion!==2)return collectionOldParseView(x);const r=x.request;return collectionOldParseView({...x,issue:{...x.issue,version:r.version||'未知',build:r.build||'未知'}}).replace('应用版本 / 构建','日志声明版本 / 构建').replace('日志范围<br>','请求时段<br>');};
// Earlier legacy renders cannot resolve newly introduced stable source keys.
// Restore the saved selection only after this adapter has made those keys visible.
if(typeof initialWorkspaceSelection!=='undefined'){
 const saved=initialWorkspaceSelection;
 if(state.issues.some(i=>i.id===saved.active))state.active=saved.active;
 for(const key of ['collectionKey','logKey'])if(fullLogSources().some(x=>x.key===saved.workspace[key]))workUI[key]=saved.workspace[key];
 for(const [id,key] of Object.entries(saved.desk.issueKeys||{}))if(fullLogSources().some(x=>x.key===key))desk.issueKeys[id]=key;
 const focus=saved.desk.focusBySource?.[page==='workbench'?desk.issueKeys[state.active]:workUI.logKey];
 if(focus){selected=focus.selected;query=focus.query||'';level=focus.level||'全部';contextMode=!!focus.contextMode;desk.module=focus.module||'';desk.from=focus.from||'';desk.to=focus.to||'';}
}
render();
